*{box-sizing:border-box} :root{--ink:#f7f5e9;--muted:#c0d0bd;--gold:#e5b968;--deep:#123a37;--panel:rgba(13,44,41,.82)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#174c46;color:var(--ink);font-family:'DM Sans','Noto Sans Malayalam',sans-serif}button{font:inherit;color:inherit;border:0;cursor:pointer}.game-shell{position:relative;width:100%;height:100dvh;overflow:hidden;background:#4f9b72}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,38,34,.5),transparent 19%,transparent 72%,rgba(8,30,29,.48)),linear-gradient(90deg,rgba(8,36,32,.18),transparent 40%,transparent 75%,rgba(9,34,32,.18));z-index:1}.glass{background:var(--panel);border:1px solid rgba(236,232,193,.2);box-shadow:0 12px 35px rgba(4,24,21,.18);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}.topbar{position:absolute;z-index:3;left:0;right:0;top:0;padding:24px 34px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:39px;height:39px;display:grid;place-items:center;border-radius:13px 13px 13px 4px;background:#e6bc69;color:#234a3e;font-family:'Noto Sans Malayalam';font-weight:800;font-size:21px;box-shadow:0 4px 16px #132f2a66}.brand-name{font-family:'Noto Sans Malayalam';font-weight:800;font-size:18px;line-height:1.2}.brand-name span{font:700 9px 'DM Sans';letter-spacing:1.6px;color:#edc872;margin-left:5px}.brand-sub{font-size:8px;letter-spacing:2px;color:#e3e7d4;margin-top:3px}.top-actions{display:flex;align-items:center;gap:10px}.weather{display:flex;align-items:center;gap:7px;margin-right:8px;font-size:9px;font-weight:700;letter-spacing:1.1px;color:#fff4d9}.sun{color:#f5c862;font-size:18px}.icon-btn{width:39px;height:39px;border-radius:12px;background:rgba(13,49,44,.68);border:1px solid #ffffff35;font-size:19px;backdrop-filter:blur(8px)}.left-panel{position:absolute;z-index:2;left:34px;top:106px;width:300px;padding:20px 21px 16px;border-radius:17px 17px 17px 4px}.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.7px;color:#eac977}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#a8d789;margin-right:6px;box-shadow:0 0 9px #a8d789}.left-panel h1{font-family:'Noto Sans Malayalam';font-size:27px;line-height:1.35;margin:11px 0 2px;font-weight:800}.district-en{font-size:9px;font-weight:700;letter-spacing:1.8px;color:#c3d6c6}.route-divider{display:flex;align-items:center;gap:10px;margin:14px 0 13px;color:#e4bd70}.route-divider span{height:1px;background:#c2d5b055;flex:1}.route-divider i{font-style:normal;font-size:10px}.mission-label{font-size:8px;letter-spacing:1.55px;color:#d4bd7d;font-weight:700}.mission-title{font-family:'Noto Sans Malayalam';font-weight:700;font-size:16px;margin-top:8px}.mission-text{font-family:'Noto Sans Malayalam';font-size:11px;line-height:1.7;color:#d0dfd0;margin:5px 0 13px}.destination{display:flex;align-items:center;gap:9px;padding:10px;background:#f3e7c713;border:1px solid #d5c88727;border-radius:9px}.destination-pin{width:28px;height:28px;display:grid;place-items:center;background:#e6bc6922;color:#edc876;border-radius:8px;font-size:17px}.destination div:nth-child(2){flex:1;min-width:0}.destination small,.location-chip small,.stats small{display:block;color:#aabfae;font-size:7px;letter-spacing:1.25px;font-weight:700;margin-bottom:3px}.destination strong{font-size:9px;white-space:nowrap;letter-spacing:.3px}.destination>span{font-size:9px;color:#eccd82;font-weight:700}.right-panel{position:absolute;z-index:2;right:34px;top:106px;width:197px}.minimap-card{padding:12px 13px 10px;border-radius:16px 16px 4px 16px}.mini-head{display:flex;justify-content:space-between;align-items:center;font-size:8px;font-weight:800;letter-spacing:1px;color:#dbe5d2}.mini-head span:last-child{color:#eac977}.minimap-card canvas{display:block;width:100%;height:174px;margin:6px auto 4px}.mini-foot{font-size:7px;letter-spacing:1px;color:#c3d4c2;display:flex;align-items:center;gap:5px}.legend-dot{width:6px;height:6px;border-radius:50%;background:#f3c45f;box-shadow:0 0 8px #f4c45f}.legend-dash{margin-left:auto;color:#e6c876;font-size:15px;line-height:4px}.map-link{margin:10px -2px 0;padding:9px 5px 0;width:100%;text-align:left;background:none;border-top:1px solid #e7e4c522;color:#e7c878;font-size:8px;letter-spacing:1px;font-weight:800}.map-link span{float:right}.stats{margin-top:9px;border-radius:12px;padding:11px 13px;display:flex;align-items:center;gap:9px}.stats>div:nth-child(2){flex:1}.stats strong{font-size:14px;font-weight:700}.stats em{font-size:8px;font-style:normal;color:#bbcbb7}.stat-icon{font-size:20px;color:#ecc879}.stat-sep{height:26px;width:1px;background:#ffffff25}.bottom-hud{position:absolute;z-index:2;left:34px;right:34px;bottom:22px;display:flex;align-items:flex-end;gap:9px}.location-chip{padding:10px 13px;display:flex;align-items:center;gap:9px;border-radius:12px 12px 4px 12px;min-width:210px}.loc-symbol{color:#eac977;font-size:19px}.location-chip strong{font-size:9px;letter-spacing:.6px}.speed{display:flex;align-items:center;gap:11px;padding:9px 12px;border-radius:11px;min-width:142px}.speed>div:first-child{display:flex;align-items:baseline;gap:4px}.speed strong{font-size:23px;line-height:1}.speed small{font-size:7px;color:#d1ddc8}.speed-bar{width:43px;height:3px;background:#ffffff36;border-radius:5px;overflow:hidden}.speed-bar span{display:block;height:100%;width:0;background:#edc873;transition:width .2s}.gear{font-size:10px;font-weight:800;color:#ebc873}.controls-hint{margin-left:auto;padding:8px 10px;border-radius:10px;display:flex;align-items:center;gap:4px}.controls-hint kbd{width:19px;height:19px;display:grid;place-items:center;border-radius:4px;background:#ffffff22;font-size:9px;font-family:inherit;font-weight:700}.controls-hint span{font-size:7px;letter-spacing:.8px;margin-left:5px;color:#d4dfd0}.touch-controls{display:none;position:absolute;z-index:4;bottom:25px;left:20px;right:20px;align-items:flex-end;justify-content:space-between;pointer-events:none}.steer-wrap,.pedal-wrap{display:flex;gap:10px;align-items:flex-end;pointer-events:auto}.pedal-wrap{align-items:flex-end}.touch-btn{pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none;background:rgba(17,54,49,.66);border:1px solid #fff6;color:white;backdrop-filter:blur(8px);box-shadow:0 4px 16px #122c2a44}.steer-left,.steer-right{width:55px;height:55px;border-radius:50%;font-size:33px;line-height:1;color:#f5d17b}.gas,.brake{display:flex;flex-direction:column;justify-content:center;align-items:center;border-radius:50%;width:59px;height:59px}.gas{width:70px;height:70px;background:rgba(210,160,71,.76)}.gas span,.brake span{font-size:21px;line-height:1}.gas small,.brake small{font-size:7px;letter-spacing:1px;font-weight:800}.interact-button{display:none;position:absolute;z-index:4;bottom:115px;right:26px;padding:10px 14px;border-radius:12px;background:#edc66c;color:#153e37;box-shadow:0 4px 14px #153c3866;font-size:11px;align-items:center;gap:7px}.interact-button span{font-size:16px}.interact-button small{font-size:7px;opacity:.7}.toast{position:absolute;z-index:8;top:85px;left:50%;transform:translate(-50%,-12px);padding:11px 18px;border:1px solid #fff4;border-radius:30px;background:rgba(13,48,42,.92);font-family:'Noto Sans Malayalam';font-size:12px;opacity:0;pointer-events:none;transition:.3s;white-space:nowrap;box-shadow:0 10px 25px #102f2d55}.toast.show{opacity:1;transform:translate(-50%,0)}.map-overlay{position:absolute;inset:0;z-index:7;background:#0b2523bd;backdrop-filter:blur(8px);display:none;align-items:center;justify-content:center;padding:22px}.map-overlay.open{display:flex}.map-sheet{width:min(920px,100%);max-height:min(770px,94dvh);overflow:auto;border:1px solid #ffffff2d;background:linear-gradient(145deg,#174a43,#103a37);box-shadow:0 25px 90px #041e1dcc;border-radius:23px;padding:27px}.map-title-row{display:flex;justify-content:space-between;align-items:flex-start}.map-title-row h2{font-family:'Noto Sans Malayalam';font-size:24px;margin:8px 0 1px}.map-title-row p{font-family:'Noto Sans Malayalam';font-size:11px;color:#c6d6c7;margin:5px 0 0}.close-map{background:#ffffff17;border:1px solid #ffffff33;border-radius:50%;width:36px;height:36px;font-size:23px}.district-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:23px 0 17px}.district-card{padding:11px 12px;border-radius:11px;background:#ffffff0b;border:1px solid #ffffff19;display:flex;align-items:center;gap:9px;min-height:61px;position:relative}.district-card.current{background:#e8c36b21;border-color:#e8c36b88}.district-card.visited:after{content:'✓';position:absolute;right:9px;top:7px;color:#c9e6a3;font-size:10px}.district-num{font-size:9px;color:#edc66d;font-weight:800}.district-card strong{display:block;font-family:'Noto Sans Malayalam';font-size:11px}.district-card small{display:block;font-size:7px;letter-spacing:.8px;color:#b9cbb9;margin-top:3px}.map-footer{border-top:1px solid #ffffff21;padding-top:13px;display:flex;justify-content:space-between;color:#c5d5c3;font-size:8px;letter-spacing:1px}.map-footer span{display:flex;align-items:center;gap:7px}.map-you{width:7px;height:7px;border-radius:50%;background:#edc66d;box-shadow:0 0 9px #edc66d}.start-screen{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:linear-gradient(180deg,#092f2b83,#103b36a3);backdrop-filter:blur(4px);transition:opacity .7s,visibility .7s}.start-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-card{width:min(400px,calc(100% - 34px));text-align:center;padding:35px 30px 29px;border:1px solid #f3e4bd54;border-radius:25px;background:linear-gradient(145deg,rgba(17,66,57,.94),rgba(12,45,43,.96));box-shadow:0 28px 90px #082a28a8}.start-logo{width:52px;height:52px;margin:0 auto 18px;border-radius:17px 17px 17px 5px;display:grid;place-items:center;background:#e8c46f;color:#244a3c;font-family:'Noto Sans Malayalam';font-weight:800;font-size:27px}.start-card h2{font-family:'Noto Sans Malayalam';font-size:42px;line-height:1.25;margin:6px 0 5px}.start-card p{font-family:'Noto Sans Malayalam';font-size:14px;line-height:1.85;color:#d4e0ce;margin:10px 0 16px}.start-tags{display:flex;justify-content:center;gap:5px;margin-bottom:20px}.start-tags span{font-size:7px;letter-spacing:.7px;font-weight:800;padding:6px 8px;border:1px solid #ead18a4d;border-radius:30px;color:#e9cf89}.start-card button{width:100%;height:48px;border-radius:12px;background:#e9c46c;color:#21493d;font-family:'Noto Sans Malayalam';font-size:14px;font-weight:800}.start-card button span{font:20px 'DM Sans';margin-left:7px}.start-card>small{display:block;margin-top:14px;font-size:7px;color:#b3c8b7;letter-spacing:1px}
@media(max-width:700px){.topbar{padding:15px 16px}.brand-mark{width:34px;height:34px}.brand-name{font-size:16px}.brand-sub{font-size:7px}.weather{font-size:7px;gap:4px;margin-right:1px}.sun{font-size:15px}.icon-btn{width:34px;height:34px;border-radius:10px}.left-panel{top:72px;left:13px;width:min(240px,calc(100vw - 120px));padding:13px 13px 11px;border-radius:13px 13px 13px 4px}.left-panel h1{font-size:20px;margin-top:6px}.district-en{font-size:7px}.route-divider{margin:8px 0}.mission-label{font-size:6px}.mission-title{font-size:13px;margin-top:5px}.mission-text{font-size:9px;line-height:1.5;margin:3px 0 8px}.destination{gap:6px;padding:7px}.destination-pin{width:23px;height:23px}.destination small{font-size:6px}.destination strong{font-size:7px}.destination>span{font-size:7px}.right-panel{right:12px;top:72px;width:103px}.minimap-card{padding:8px 7px;border-radius:12px 12px 4px 12px}.mini-head{font-size:6px;letter-spacing:.4px}.minimap-card canvas{height:126px;margin:4px auto}.mini-foot{font-size:5px;gap:3px;letter-spacing:.4px}.legend-dot{width:5px;height:5px}.map-link{font-size:6px;padding-top:7px;margin-top:7px}.stats{margin-top:6px;padding:7px 8px;gap:5px;border-radius:9px}.stats strong{font-size:10px}.stats em,.stats small{font-size:6px}.stats small{letter-spacing:.3px}.stat-icon{font-size:14px}.stat-sep{height:21px}.bottom-hud{left:12px;right:12px;bottom:14px;gap:6px}.location-chip{min-width:0;padding:7px 8px;gap:5px;max-width:155px}.loc-symbol{font-size:15px}.location-chip small{font-size:5px;letter-spacing:.6px}.location-chip strong{font-size:7px;letter-spacing:.2px}.speed{min-width:0;padding:7px 8px;gap:6px}.speed strong{font-size:18px}.speed small{font-size:6px}.speed-bar{width:25px}.gear{font-size:8px}.controls-hint{display:none}.touch-controls{display:flex}.interact-button{display:flex}.toast{top:64px;max-width:90%;font-size:10px;padding:9px 12px}.map-sheet{padding:20px 15px;border-radius:18px}.map-title-row h2{font-size:19px}.map-title-row p{font-size:9px}.district-grid{grid-template-columns:repeat(2,1fr);gap:6px;margin:16px 0 12px}.district-card{padding:8px;gap:6px;min-height:52px}.district-card strong{font-size:10px}.district-card small{font-size:6px}.map-footer{font-size:6px}.start-card{padding:28px 21px 23px}.start-card h2{font-size:37px}.start-card p{font-size:12px}.start-tags span{font-size:6px;padding:6px}.start-card>small{font-size:6px}}
@media(max-height:650px) and (min-width:701px){.left-panel{top:80px;padding:14px 16px;width:270px}.right-panel{top:80px}.minimap-card canvas{height:135px}.bottom-hud{bottom:12px}.topbar{padding:15px 25px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const W = 2300, GAP = 650, TOP = 430;
  const districts = [
    ['കാസർഗോഡ്','KASARAGOD','ബേക്കൽ കോട്ട','BEKAL FORT','cliffs'],
    ['കണ്ണൂർ','KANNUR','മുഴപ്പിലങ്ങാട് ബീച്ച്','MUZHAPPILANGAD BEACH','coast'],
    ['വയനാട്','WAYANAD','എടക്കൽ ഗുഹകൾ','EDAKKAL CAVES','hills'],
    ['കോഴിക്കോട്','KOZHIKODE','മാനാഞ്ചിറ','MANANCHIRA','city'],
    ['മലപ്പുറം','MALAPPURAM','കോട്ടക്കുന്ന്','KOTTAKKUNNU','hills'],
    ['പാലക്കാട്','PALAKKAD','മലമ്പുഴ അണക്കെട്ട്','MALAMPUZHA DAM','hills'],
    ['തൃശ്ശൂർ','THRISSUR','വടക്കുന്നാഥൻ ക്ഷേത്രം','VADAKKUNNATHAN TEMPLE','temple'],
    ['എറണാകുളം','ERNAKULAM','ഫോർട്ട് കൊച്ചി','FORT KOCHI','harbor'],
    ['ആലപ്പുഴ','ALAPPUZHA','ആലപ്പുഴ കായൽ','ALAPPUZHA BACKWATERS','water'],
    ['കോട്ടയം','KOTTAYAM','കുമരകം','KUMARAKOM','water'],
    ['ഇടുക്കി','IDUKKI','മുന്നാർ ടീ ഗാർഡൻ','MUNNAR TEA GARDENS','hills'],
    ['പത്തനംതിട്ട','PATHANAMTHITTA','ഗവി കാട്','GAVI FOREST','forest'],
    ['കൊല്ലം','KOLLAM','അഷ്ടമുടി കായൽ','ASHTAMUDI LAKE','water'],
    ['തിരുവനന്തപുരം','THIRUVANANTHAPURAM','കോവളം കടൽത്തീരം','KOVALAM BEACH','coast']
  ].map((d,i)=>({ml:d[0],en:d[1],spot:d[2],spotEn:d[3],type:d[4],x:1180+Math.sin(i*1.17)*330+Math.sin(i*.43)*125,y:TOP+i*GAP,visited:false}));
  const startIdx=7;
  districts[startIdx].visited=true;
  const car={x:districts[startIdx].x,y:districts[startIdx].y+54,angle:Math.PI/2,speed:0,steer:0};
  let dpr=1, vw=innerWidth, vh=innerHeight, last=performance.now(), elapsed=0, soundOn=true, toastTimer=0, mapOpen=false, started=false, totalDistance=0, deliveries=0, nearIdx=startIdx;
  let targetIdx=8;
  const keys=new Set(), touch={left:false,right:false,gas:false,brake:false};
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const rand=(n)=>{let x=Math.sin(n*127.1+31.7)*43758.5453;return x-Math.floor(x)};
  function resize(){dpr=Math.min(devicePixelRatio||1,2);vw=innerWidth;vh=innerHeight;canvas.width=Math.round(vw*dpr);canvas.height=Math.round(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawMini()}
  addEventListener('resize',resize,{passive:true});resize();
  function roadX(y){let n=clamp((y-TOP)/GAP,0,districts.length-1),i=Math.min(districts.length-2,Math.floor(n)),t=clamp(n-i,0,1);if(n>=districts.length-1)return districts.at(-1).x;let a=districts[i],b=districts[i+1];let p0=districts[Math.max(0,i-1)],p3=districts[Math.min(districts.length-1,i+2)];let t2=t*t,t3=t2*t;return .5*((2*a.x)+(-p0.x+b.x)*t+(2*p0.x-5*a.x+4*b.x-p3.x)*t2+(-p0.x+3*a.x-3*b.x+p3.x)*t3)}
  const camera=()=>({x:clamp(car.x-vw*.5,0,W-vw),y:clamp(car.y-vh*.53,0,TOP+(districts.length-1)*GAP-vh*.8)});
  function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
  function drawTerrain(cam){
    ctx.fillStyle='#73aa6d';ctx.fillRect(0,0,vw,vh);
    // broad, gently varied fields
    const tile=110;let ox=-cam.x%tile,oy=-cam.y%tile;
    for(let y=oy-tile;y<vh+tile;y+=tile)for(let x=ox-tile;x<vw+tile;x+=tile){let gx=Math.floor((x+cam.x)/tile),gy=Math.floor((y+cam.y)/tile),r=rand(gx*991+gy*31);ctx.fillStyle=r>.75?'#78ad72':r<.2?'#6da36b':'#73aa6d';ctx.fillRect(x,y,tile+1,tile+1);if(r>.82){ctx.globalAlpha=.12;ctx.fillStyle='#e2d58c';ctx.beginPath();ctx.ellipse(x+25,y+70,32,14,-.2,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
    // winding blue-green rivers, far from main road
    ctx.save();ctx.translate(-cam.x,-cam.y);ctx.lineCap='round';
    for(let i=0;i<districts.length-1;i+=2){let d=districts[i], yy=d.y+250, xx=d.x+(i%4<2?390:-450);ctx.beginPath();ctx.moveTo(xx-80,yy-250);ctx.bezierCurveTo(xx+150,yy-100,xx-150,yy+40,xx+40,yy+290);ctx.strokeStyle='#4b9e9a';ctx.lineWidth=70;ctx.stroke();ctx.strokeStyle='#80c3ac';ctx.lineWidth=4;ctx.stroke()}
    // small paddy channels
    for(let i=0;i<districts.length;i++){let d=districts[i], side=i%2?1:-1;ctx.beginPath();ctx.moveTo(d.x+side*230,d.y+170);ctx.quadraticCurveTo(d.x+side*360,d.y+270,d.x+side*260,d.y+410);ctx.strokeStyle='#559f8d';ctx.lineWidth=16;ctx.stroke()}
    ctx.restore();
    // palms and shade trees: deterministic, comfortably off-road
    const top=cam.y-100,bottom=cam.y+vh+100;
    for(let i=0;i<200;i++){let y=TOP-150+i*64;if(y<top||y>bottom)continue;for(let s of [-1,1]){let x=roadX(y)+s*(170+rand(i*7+s*5)*430);if(x<35||x>W-35)continue;drawTree(x-cam.x,y-cam.y,rand(i*17+s*11))}}
  }
  function drawTree(x,y,r){ctx.save();ctx.translate(x,y);let scale=.7+r*.75;ctx.fillStyle='#214d3d';ctx.beginPath();ctx.ellipse(3,8,11*scale,8*scale,0,0,7);ctx.fill();ctx.fillStyle=r>.5?'#32794f':'#3e8650';ctx.beginPath();ctx.ellipse(0,0,10*scale,8*scale,0,0,7);ctx.fill();ctx.fillStyle='#6ba05a';ctx.beginPath();ctx.ellipse(-3,-3,4*scale,3*scale,-.3,0,7);ctx.fill();ctx.restore()}
  function drawRoad(cam){ctx.save();ctx.translate(-cam.x,-cam.y);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();for(let y=TOP-500;y<=TOP+(districts.length-1)*GAP+500;y+=18){let x=roadX(y);if(y===TOP-500)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.strokeStyle='#507357';ctx.lineWidth=126;ctx.stroke();ctx.strokeStyle='#b9aa78';ctx.lineWidth=112;ctx.stroke();ctx.strokeStyle='#59665a';ctx.lineWidth=94;ctx.stroke();ctx.strokeStyle='#647065';ctx.lineWidth=83;ctx.stroke();ctx.setLineDash([17,22]);ctx.strokeStyle='#e3cf83';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash([]);
    // roadside village lanes, town huts, tea plots, and named landmarks
    for(let i=0;i<districts.length;i++){let d=districts[i], side=i%2?1:-1, lx=d.x+side*128,ly=d.y+10;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.quadraticCurveTo(d.x+side*65,d.y+20,lx,ly);ctx.strokeStyle='#7b7f66';ctx.lineWidth=22;ctx.stroke();ctx.strokeStyle='#cdc08a';ctx.lineWidth=17;ctx.stroke();ctx.strokeStyle='#676d60';ctx.lineWidth=13;ctx.stroke();
      // compact little town blocks
      for(let j=0;j<11;j++){let bx=d.x+(rand(i*29+j*3)-.5)*230,by=d.y+(rand(i*33+j*13)-.5)*150;if(Math.abs(bx-d.x)<62)continue;drawHouse(bx,by,i,j)}
      drawLandmark(d,side);
    }
    ctx.restore()}
  function drawHouse(x,y,i,j){let w=18+rand(i*13+j)*20,h=13+rand(j*17+i)*15;ctx.fillStyle='#49694c';ctx.fillRect(x-w/2+3,y-h/2+5,w,h);ctx.fillStyle=['#d7c79d','#c4d2a3','#e5b678','#d8ddd0'][Math.floor(rand(i+j*3)*4)];ctx.fillRect(x-w/2,y-h/2,w,h);ctx.fillStyle=['#9d5c43','#b7784b','#78574b'][Math.floor(rand(i*7+j)*3)];ctx.beginPath();ctx.moveTo(x-w/2-3,y-h/2);ctx.lineTo(x,y-h/2-8);ctx.lineTo(x+w/2+3,y-h/2);ctx.closePath();ctx.fill();ctx.fillStyle='#775843';ctx.fillRect(x-2,y+2,5,h/2)}
  function drawLandmark(d,side){let x=d.x+side*135,y=d.y-52;const colors={hills:'#a5b779',coast:'#7ec7bd',water:'#74bfc1',harbor:'#dfb06a',city:'#d2c68d',temple:'#dca970',forest:'#72a273',cliffs:'#bb9371'};ctx.save();ctx.translate(x,y);ctx.fillStyle='#173b35aa';ctx.beginPath();ctx.ellipse(0,29,69,13,0,0,7);ctx.fill();
    if(d.type==='temple'){ctx.fillStyle='#d9b979';ctx.fillRect(-28,-20,56,39);ctx.fillStyle='#884b3b';ctx.beginPath();ctx.moveTo(-34,-20);ctx.lineTo(0,-43);ctx.lineTo(34,-20);ctx.fill();for(let k=0;k<4;k++){ctx.fillStyle='#e6d3a0';ctx.fillRect(-19+k*10,-13,6,12)}}
    else if(d.type==='water'||d.type==='coast'||d.type==='harbor'){ctx.fillStyle=colors[d.type];ctx.beginPath();ctx.ellipse(0,0,37,18,0,0,7);ctx.fill();ctx.fillStyle='#f3dfaa';ctx.fillRect(-31,8,62,3);ctx.fillStyle='#6d4836';ctx.beginPath();ctx.moveTo(-9,2);ctx.lineTo(12,2);ctx.lineTo(5,9);ctx.lineTo(-14,9);ctx.fill();ctx.fillStyle='#f4dd99';ctx.beginPath();ctx.moveTo(-3,-2);ctx.lineTo(-3,-17);ctx.lineTo(7,-4);ctx.fill()}
    else{ctx.fillStyle=colors[d.type]||'#b7ae78';ctx.beginPath();ctx.ellipse(0,0,33,22,0,0,7);ctx.fill();if(d.type==='cliffs'||d.type==='hills'||d.type==='forest'){ctx.fillStyle='#577b4b';ctx.beginPath();ctx.moveTo(-32,4);ctx.lineTo(-12,-25);ctx.lineTo(1,-2);ctx.lineTo(19,-30);ctx.lineTo(35,5);ctx.fill();ctx.fillStyle='#e7d99b';ctx.beginPath();ctx.moveTo(-16,-19);ctx.lineTo(-12,-25);ctx.lineTo(-8,-20);ctx.fill()}}
    ctx.restore();ctx.beginPath();ctx.arc(x,y+21,4,0,7);ctx.fillStyle='#f4ce76';ctx.fill();ctx.strokeStyle='#244e41';ctx.lineWidth=2;ctx.stroke();
    rounded(x-78,y-75,156,22,7,'#153e37de','#f0dda04d');ctx.fillStyle='#fff4d8';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='700 8px "DM Sans"';ctx.fillText(d.spotEn,x,y-64);ctx.fillStyle='#edcb77';ctx.beginPath();ctx.arc(x-67,y-64,2,0,7);ctx.fill();
    // district name plaque
    rounded(d.x-67,d.y+88,134,25,7,'#133b36e8','#e6ce8e44');ctx.fillStyle='#edd083';ctx.font='700 7px "DM Sans"';ctx.fillText(String(iDistrict(d)+1).padStart(2,'0')+'  ·  '+d.en,x,d.y+100);
  }
  function iDistrict(d){return districts.indexOf(d)}
  function drawCar(){ctx.save();ctx.translate(car.x-camera().x,car.y-camera().y);ctx.rotate(car.angle);ctx.shadowColor='#172e25';ctx.shadowBlur=14;ctx.shadowOffsetY=8;
    // rickshaw wheels, chassis and bright curved cabin
    ctx.fillStyle='#24342b';ctx.beginPath();ctx.roundRect(-14,-22,28,47,8);ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;
    ctx.fillStyle='#d9aa4f';ctx.beginPath();ctx.roundRect(-12,-23,24,17,5);ctx.fill();ctx.fillStyle='#157457';ctx.beginPath();ctx.roundRect(-12,-7,24,27,6);ctx.fill();
    ctx.fillStyle='#a5d1b4';ctx.beginPath();ctx.roundRect(-8,-17,16,8,3);ctx.fill();ctx.fillStyle='#183d32';ctx.fillRect(-7,-5,14,10);ctx.fillStyle='#f6d675';ctx.fillRect(-12,15,5,4);ctx.fillRect(7,15,5,4);ctx.fillStyle='#f2e7b6';ctx.fillRect(-10,-24,5,3);ctx.fillRect(5,-24,5,3);
    ctx.fillStyle='#1e3028';for(let x of [-15,11]){ctx.fillRect(x,-15,4,10);ctx.fillRect(x,9,4,10)}ctx.restore()}
  function drawMini(){if(!mctx)return;let w=mini.width,h=mini.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#153f3a';mctx.fillRect(0,0,w,h);let xOf=x=>w*(.18+(x/W)*.64),yOf=y=>h*(.06+(y/(TOP+(districts.length-1)*GAP))*.88);mctx.lineCap='round';mctx.beginPath();districts.forEach((d,i)=>i?mctx.lineTo(xOf(d.x),yOf(d.y)):mctx.moveTo(xOf(d.x),yOf(d.y)));mctx.strokeStyle='#c8b87f';mctx.lineWidth=Math.max(3,w*.025);mctx.stroke();districts.forEach((d,i)=>{mctx.beginPath();mctx.arc(xOf(d.x),yOf(d.y),i===targetIdx?4:2.6,0,7);mctx.fillStyle=i===targetIdx?'#f4cb69':d.visited?'#c5df9d':'#83aa88';mctx.fill()});mctx.beginPath();mctx.arc(xOf(car.x),yOf(car.y),4.6,0,7);mctx.fillStyle='#fff0bb';mctx.fill();mctx.strokeStyle='#f2c65f';mctx.lineWidth=1.5;mctx.stroke()}
  function updateHud(){const nearest=nearestDistrict();nearIdx=nearest.i;let target=districts[targetIdx],distance=Math.hypot(car.x-target.x,car.y-target.y);document.getElementById('districtTitle').textContent=districts[nearIdx].ml;document.getElementById('districtEnglish').textContent=districts[nearIdx].en+' DISTRICT';document.getElementById('locationLabel').textContent=districts[nearIdx].spotEn+' · '+districts[nearIdx].en;document.getElementById('destinationText').textContent=target.ml+' · '+target.en;document.getElementById('distanceText').textContent=(distance*4.3/1000).toFixed(1)+' km';document.getElementById('visitedCount').textContent=String(districts.filter(d=>d.visited).length).padStart(2,'0')+' / 14';document.getElementById('deliveries').innerHTML=deliveries+' <em>/ 14</em>';document.getElementById('miles').innerHTML=(totalDistance*4.3/1000).toFixed(1)+' <em>km</em>';document.getElementById('speedValue').textContent=Math.round(Math.abs(car.speed)*.53);document.getElementById('speedFill').style.width=Math.min(100,Math.abs(car.speed)/2.6)+'%';const nearTarget=distance<115;const ib=document.getElementById('interactButton');ib.style.opacity=nearTarget?'1':'.65';ib.querySelector('small').textContent=nearTarget?'READY!':'NEAR A STOP';document.getElementById('missionText').textContent=deliveries>=14?'എല്ലാ ജില്ലകളിലും നന്മയുടെ ഒരു കൈനീട്ടം! ഇനി ഇഷ്ടമുള്ള വഴിയിലൂടെ സഞ്ചരിക്കൂ.':`${target.spot} വഴി പോകുന്ന കൂട്ടുകാരന് ഒരു ഓണസദ്യ എത്തിക്കണം. അടുത്ത സ്റ്റോപ്പിൽ എത്തി DELIVER അമർത്തൂ.`;drawMini()}
  function nearestDistrict(){let best=Infinity,idx=0;for(let i=0;i<districts.length;i++){let d=districts[i],dist=Math.abs(car.y-d.y)+Math.abs(car.x-d.x)*.24;if(dist<best){best=dist;idx=i}}return{i:idx,d:best}}
  function showToast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
  function visitCheck(){for(let i=0;i<districts.length;i++){const d=districts[i];if(!d.visited&&Math.hypot(car.x-d.x,car.y-d.y)<115){d.visited=true;showToast('പുതിയ ജില്ല കണ്ടുപിടിച്ചു · '+d.ml+' ✨');drawMini()}}}
  function deliver(){let d=districts[targetIdx];if(Math.hypot(car.x-d.x,car.y-d.y)>145){showToast('അടുത്ത സ്റ്റോപ്പിലേക്ക് കുറച്ച് കൂടി പോകൂ!');return}if(targetIdx===startIdx&&deliveries===0){showToast('യാത്ര തുടങ്ങട്ടെ — അടുത്ത സ്റ്റോപ്പ് '+d.ml+'!');return}deliveries++;d.visited=true;showToast('ഓണസദ്യ എത്തിച്ചു! നന്മയ്ക്ക് നന്ദി · +100 ✨');let next=-1;for(let n=1;n<=districts.length;n++){let candidate=(targetIdx+n)%districts.length;if(!districts[candidate].visited){next=candidate;break}}if(next>=0)targetIdx=next;else{deliveries=Math.min(deliveries,14);targetIdx=(targetIdx+1)%districts.length}visitCheck();updateHud()}
  function inputState(){let gas=keys.has('w')||keys.has('arrowup')||touch.gas, brake=keys.has('s')||keys.has('arrowdown')||touch.brake,left=keys.has('a')||keys.has('arrowleft')||touch.left,right=keys.has('d')||keys.has('arrowright')||touch.right;return{gas,brake,left,right}}
  function frame(now){let dt=Math.min(.04,(now-last)/1000);last=now;elapsed+=dt;if(started&&!mapOpen){let inp=inputState();let steer=(inp.right?1:0)-(inp.left?1:0);if(inp.gas)car.speed=Math.min(285,car.speed+175*dt);else if(inp.brake)car.speed=Math.max(-90,car.speed-260*dt);else car.speed*=Math.pow(.985,dt*60);if(Math.abs(car.speed)<.5)car.speed=0;car.steer+=(steer-car.steer)*Math.min(1,dt*7);car.angle+=car.steer*dt*(.65+Math.min(1,Math.abs(car.speed)/95))*(car.speed<0?-1:1);let oldX=car.x,oldY=car.y;car.x=clamp(car.x+Math.cos(car.angle)*car.speed*dt,45,W-45);car.y=clamp(car.y+Math.sin(car.angle)*car.speed*dt,TOP-180,TOP+(districts.length-1)*GAP+180);totalDistance+=Math.hypot(car.x-oldX,car.y-oldY);visitCheck();if(Math.floor(elapsed*3)%3===0)updateHud()}
    let cam=camera();ctx.setTransform(dpr,0,0,dpr,0,0);drawTerrain(cam);drawRoad(cam);drawCar();drawMini();requestAnimationFrame(frame)}
  requestAnimationFrame(frame);
  addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(k==='e'||k===' ')deliver();if(k==='m')toggleMap()});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  function toggleMap(){mapOpen=!mapOpen;document.getElementById('mapOverlay').classList.toggle('open',mapOpen);document.getElementById('mapOverlay').setAttribute('aria-hidden',String(!mapOpen));if(mapOpen)renderDistrictGrid()}
  function renderDistrictGrid(){let grid=document.getElementById('districtGrid');grid.innerHTML='';districts.forEach((d,i)=>{let el=document.createElement('div');el.className='district-card'+(d.visited?' visited':'')+(i===nearIdx?' current':'');el.innerHTML=`<span class="district-num">${String(i+1).padStart(2,'0')}</span><div><strong>${d.ml}</strong><small>${d.en} · ${d.spotEn}</small></div>`;grid.appendChild(el)})}
  document.getElementById('mapButton').onclick=toggleMap;document.getElementById('openMap').onclick=toggleMap;document.getElementById('closeMap').onclick=toggleMap;
  document.getElementById('mapOverlay').addEventListener('click',e=>{if(e.target.id==='mapOverlay')toggleMap()});
  document.getElementById('interactButton').onclick=deliver;
  document.getElementById('soundButton').onclick=()=>{soundOn=!soundOn;document.getElementById('soundButton').style.opacity=soundOn?'1':'.45';showToast(soundOn?'ശബ്ദം ഓൺ':'ശബ്ദം ഓഫ്')};
  document.getElementById('startButton').onclick=()=>{started=true;document.getElementById('startScreen').classList.add('hidden');showToast('എറണാകുളത്ത് നിന്ന് യാത്ര തുടങ്ങി · ആലപ്പുഴയിലേക്ക് പോവൂ!')};
  document.querySelectorAll('[data-control]').forEach(btn=>{const key=btn.dataset.control;btn.addEventListener('pointerdown',e=>{e.preventDefault();btn.setPointerCapture(e.pointerId);touch[key]=true});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,e=>{e.preventDefault();touch[key]=false}))});
  updateHud();
})();

