content.text:
.district-card{padding:11px 12px;border-radius:11px;background:#ffffff0b;border:1px solid #ffffff19;display:flex;align-items:center;gap:9px;min-height:61px;position:relative}
.district-card.current{background:#e8c36b21;border-color:#e8c36b88}
.district-card.visited:after{content:'✓';position:absolute;right:9px;top:7px;color:#c9e6a3;font-size:10px}
.district-card strong{display:block;font-family:'Noto Sans Malayalam';font-size:11px}
.district-card small{display:block;font-size:7px;letter-spacing:.8px;color:#b9cbb9;margin-top:3px}
.district-card{padding:8px;gap:6px;min-height:52px}
.district-card strong{font-size:10px}
.district-card small{font-size:6px}

